      "B": "reduzir todo o currículo anual ao treinamento repetitivo de gabaritos de língua e cálculo.",
      "C": "excluir alunos com deficiência nos dias de prova visando elevar artificialmente as médias.",
      "D": "mapear desigualdades de aprendizagem para orientar apoio técnico, equidade e intervenções."
