    "correct": "B",
    "explanation": "Gabarito: Letra B. Wallon concebe o desenvolvimento infantil como uma totalidade dinâmica em que afetividade, motricidade e ato intelectual interagem dialeticamente na interação do sujeito com o meio cultural e social. (Aprofundamento temático de conformidade com as diretrizes do Edital SEDUC-CE nº 014/2026)."
