    "correct": "C",
    "explanation": "Gabarito: Letra C. Luckesi demonstra que a pedagogia do exame é classificatória, seletiva e punitiva, servindo para aprovar ou reprovar; enquanto a avaliação é formativa, amorosa, acolhedora e diagnóstica, servindo para intervir positivamente no desenvolvimento do estudante. (Aprofundamento temático de conformidade com as diretrizes do Edital SEDUC-CE nº 014/2026)."
