    "topicTitle": "Plano Nacional de Educação (PNE) e Diretrizes das Políticas Educacionais",
    "stem": "[FUNECE/SEDUC-CE 2026 - Item Didático #181] No contexto de \"Plano Nacional de Educação (PNE) e Diretrizes das Políticas Educacionais\", considere a seguinte reflexão pedagógica e normativa: O Plano Nacional de Educação (PNE 2014-2024 / Lei nº 13.005/2014) fixou 20 metas decenais para a educação brasileira. A Meta 1 do PNE estabelece como objetivo",
    "options": {
      "D": "universalizar a educação infantil na pré-escola para as crianças de 4 a 5 anos de idade.",
      "A": "tornar obrigatória a matrícula de todas as crianças de 0 a 3 anos de idade em creches.",
      "B": "extinguir progressivamente as creches públicas transferindo o encargo para o terceiro setor.",
      "C": "antecipar a alfabetização obrigatória para os 3 anos com aplicação de exames classificatórios."
    },
    "correct": "D",
    "explanation": "Gabarito: Letra D. A Meta 1 do PNE estabeleceu a universalização da educação infantil na pré-escola para as crianças de 4 a 5 anos de idade e a ampliação da oferta de educação infantil em creches de forma a atender, no mínimo, 50% das crianças de até 3 anos. (Aprofundamento temático de conformidade com as diretrizes do Edital SEDUC-CE nº 014/2026)."
